body.script:
var voiceData={
 robot:["Robo One","Robo Deep","Robo X","Cyber Bot","Metal Voice","Future AI","Aivora Robot"],
 female:["Anaya","Priya","Maya","Sofia","Angel","Riya","Aarohi"],
 male:["Arjun","Rahul","Aman","David","Rohan","Vikram"]
};
var selectedVoice="Robo One";

function showVoices(){
 var category=document.getElementById("category").value;
 var box=document.getElementById("voices");
 box.innerHTML="";
 voiceData[category].forEach(function(name,index){
  var div=document.createElement("div");
  div.className="voice"+(selectedVoice===name?" active":"");
  div.innerHTML=name+""+(category==="robot"?"🤖 Robot":category==="female"?"👩 Female":"👨 Male")+"";
  div.onclick=function(){
   selectedVoice=name;
   showVoices();
  };
  box.appendChild(div);
 });
}
document.getElementById("category").onchange=function(){
 selectedVoice=voiceData[this.value][0];
 showVoices();
};
showVoices();

function speak(text){
 if(!("speechSynthesis" in window)){
  document.getElementById("status").innerText="Voice preview इस browser में उपलब्ध नहीं है।";
  return;
 }
 window.speechSynthesis.cancel();
 var utter=new SpeechSynthesisUtterance(text);
 utter.lang=document.getElementById("language").value;
 utter.rate=selectedVoice.indexOf("Deep")>=0?0.8:1;
 utter.pitch=document.getElementById("category").value==="female"?1.3:
 document.getElementById("category").value==="robot"?0.75:0.95;
 window.speechSynthesis.speak(utter);
 document.getElementById("status").innerText="Playing preview: "+selectedVoice;
}
function previewVoice(){
 speak("Hello! I am "+selectedVoice+". Welcome to Aivora AI Video Studio.");
}
function previewScript(){
 speak(document.getElementById("script").value);
}
function createVideo(){
 var prompt=document.getElementById("prompt").value;
 if(!prompt.trim()){
  document.getElementById("status").innerText="Please describe your video first.";
  return;
 }
 document.getElementById("status").innerText=
 "Your video idea is ready! AI video generation engine will be connected in the next step.";
}
